            operands.push({ source: 'step', propertyName: 'preparedEsignTemplate', stepId: d.stepId, type: 'PreparedEsignTemplate', displayName: 'Prepared eSignature Template', defaultValue: { templateId: d.templateId, brandLock: 'false' } });
