                // are offered too, but their fixed texts are not harvested.
                if (s.confirm.type !== 'tasks-complete')
                    throw new Error(`${spec.id}: confirm type: "tasks-complete" (End of participant's tasks); the other prebuilt types are not harvested — write a title and description instead`);
                if (s.confirm.title !== undefined || s.confirm.description !== undefined)
                    throw new Error(`${spec.id}: confirm type: a prebuilt message has its own fixed title and body — leave out "title" and "description"`);
                const cpid = who(s.to, 'confirm').participantId;
                const st = step.confirmation({ participantId: cpid, title: 'Tasks complete', description: 'You\'ve completed all your workflow tasks.' });
                const stepId = sid(`${spec.id}:step:${i}`);
