                const state = s.closed ? 'Closed' : 'Open';
                if (statusStates.has(s.status) && statusStates.get(s.status) !== state)
                    throw new Error(`${spec.id}: status "${s.status}": closed on one step and open on another — a status has one type`);
                statusStates.set(s.status, state);
                const exS = o.existingStatuses?.[s.status];
                const statusId = exS?.id ?? sid(`${spec.id}:status:${s.status}${o.statusSalt ? `:${o.statusSalt}` : ''}`);
                // Carried with its LIVE id and name, the importer reuses it — nothing is created (probe B, 2026-10-28:
