                    extras.push({ componentId: statusId, componentType: 'AgreementDeskRequestStatus', relativePath: `agreementdeskrequeststatus/${statusId}.json`, name: statusId,
                        data: { id: statusId, name, state, deletedAt: null, isDeleted: false, color: s.color ?? 'neutral' } });
                    carries.statuses.push({ id: statusId, name });
